'use strict';

const assert = require('node:assert');
const runningTotals = require('./solution');

assert.strictEqual(typeof runningTotals, 'function');

const empty = [];
const emptyResult = runningTotals(empty);
assert.deepStrictEqual(emptyResult, []);
assert.notStrictEqual(emptyResult, empty);

const values = Object.freeze([5, -2, 0.5, 10]);
const result = runningTotals(values);
assert.deepStrictEqual(result, [5, 3, 3.5, 13.5]);
assert.notStrictEqual(result, values);
assert.deepStrictEqual(values, [5, -2, 0.5, 10]);

assert.deepStrictEqual(runningTotals([0]), [0]);
assert.deepStrictEqual(runningTotals([-3, -4]), [-3, -7]);
assert.deepStrictEqual(runningTotals([Number.MAX_VALUE, Number.MAX_VALUE]), [Number.MAX_VALUE, Infinity]);

for (const invalid of [null, undefined, {}, '1,2', 3]) {
  assert.throws(() => runningTotals(invalid), TypeError);
}
for (const invalid of [[NaN], [Infinity], [-Infinity], [1, '2'], [1, null]]) {
  assert.throws(() => runningTotals(invalid), TypeError);
}

